mapper.select:
select T1.FINPROD_MARKET_ID as id , T1.FINPROD_NAME as text from FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID where 1=1 and T1.FINPROD_TYPE2 = 'F06' and T2.TYPE_7 = '04'
and (T1.FINPROD_MARKET_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) OR T1.FINPROD_NAME like concat('%',concat(#{search,jdbcType=VARCHAR},'%')))
and T1.FINPROD_MARKET_ID =#{initValue,jdbcType=VARCHAR}

mapper.delete:
delete from FIN_PRODUCT_GOAL
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and GOAL_DATE = #{goalDate,jdbcType=DATE}

mapper.select:
select CALENDAR_ID "calendarId"
from FIN_PRODUCT
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
